{"command":"cat > /tmp/pngutil.py <<'PY'
import zlib, struct, subprocess, os, shutil
def decode(p):
    d=open(p,'rb').read(); pos=8; idat=b''; w=h=None; ct=None
    plte=None; trns=None
    while pos<len(d):
        ln=struct.unpack(">I",d[pos:pos+4])[0]; typ=d[pos+4:pos+8]; data=d[pos+8:pos+8+ln]
        if typ==b'IHDR': w,h,bd,ct,_,_,_=struct.unpack(">IIBBBBB",data)
        if typ==b'IDAT': idat+=data
        pos+=12+ln
    raw=zlib.decompress(idat)
    channels={0:1,2:3,3:1,4:2,6:4}[ct]; bpp=channels; stride=w*bpp+1; prev=bytearray(w*bpp); rows=[]
    for y in range(h):
        filt=raw[y*stride]; row=raw[y*stride+1:(y+1)*stride]; out=bytearray(w*bpp)
        for i,x in enumerate(row):
            a=out[i-bpp] if i>=bpp else 0; b=prev[i]; c=prev[i-bpp] if i>=bpp else 0
            if filt==0: v=x
            elif filt==1: v=(x+a)&255
            elif filt==2: v=(x+b)&255
            elif filt==3: v=(x+(a+b)//2)&255
            else:
                pp=a+b-c; pa=abs(pp-a); pb=abs(pp-b); pc=abs(pp-c); pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c); v=(x+pr)&255
            out[i]=v
        prev=out; rows.append(bytes(out))
    return w,h,ct,rows
def dark_cols(p):
    w,h,ct,rows=decode(p)
    cols=[]
    for x in range(w):
        dark=False
        for y in range(h):
            if ct==2:
                if rows[y][x*3]<100: dark=True
            elif ct==6:
                if rows[y][x*4+3]>0 and rows[y][x*4]<100: dark=True
            elif ct==0:
                if rows[y][x]<100: dark=True
        cols.append(1 if dark else 0)
    return cols
def render(content, extra=[]):
    base="/tmp/pngtest2"; shutil.rmtree(base,ignore_errors=True); os.makedirs(base)
    open(os.path.join(base,"in.txt"),"w").write(content)
    subprocess.run(["/workspace/executable","-S","-A"]+extra+["in.txt","out.png"], cwd=base, capture_output=True)
    return os.path.join(base,"out.png")
PY
