    public boolean debug = false;
    public boolean html = false;
    public boolean overwrite = false;
    public boolean roundCorners = false;
    public boolean noShadows = false;
    public boolean transparent = false;
    public boolean verbose = false;
    public boolean fixedSlope = false;
    public boolean svg = false;
    public boolean noSeparation = false;
    public String svgFontUrl = null;
    public Color background = null;
    public boolean hasBackground = false;
    public float scale = 1.0f;
    public int tabs = 8;
    public String encoding = null;

    public boolean dropShadows() { return !noShadows; }
    public boolean performSeparation() { return !noSeparation; }
    public Color getBackgroundColor() {
        if (transparent) return new Color(0, 0, 0, 0);
        if (hasBackground) return background;
        return new Color(255, 255, 255, 255);
    }
    public boolean isBackgroundTransparent() {
        if (transparent) return true;
        if (hasBackground && background != null && background.getAlpha() == 0) return true;
        return false;
    }
    public boolean hasAlphaBackground() {
        if (transparent) return true;
        return hasBackground && background != null && background.getAlpha() != 255;
    }
}
