package org.stathissideris.ascii2image.graphics;

import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;

public class FontMeasurer {
    private static final HashMap<Character, Double> WIDTHS = new HashMap<Character, Double>();
    private static Graphics2D scratch;

    static {
        // Approximate proportional character widths (at font size 15) for the
        // kind of sans-serif font used for measuring text in diagrams.
        String lower = "abcdefghijklmnopqrstuvwxyz";
        double[] lw = {10,10,9,10,10,7,10,10,4,4,10,4,15,10,10,10,10,7,9,7,10,9,15,10,10,9};
        for (int i = 0; i < lower.length(); i++) WIDTHS.put(lower.charAt(i), lw[i]);
        String upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        double[] uw = {12,11,12,12,10,9,13,12,6,7,12,10,14,12,13,11,13,12,11,10,12,12,18,12,12,11};
        for (int i = 0; i < upper.length(); i++) WIDTHS.put(upper.charAt(i), uw[i]);
        for (char c = '0'; c <= '9'; c++) WIDTHS.put(c, 10.0);
        WIDTHS.put(' ', 5.0);
        WIDTHS.put('.', 4.0); WIDTHS.put(',', 4.0); WIDTHS.put(':', 4.0); WIDTHS.put(';', 4.0);
        WIDTHS.put('!', 5.0); WIDTHS.put('?', 9.0); WIDTHS.put('\'', 3.0); WIDTHS.put('"', 6.0);
        WIDTHS.put('(', 5.0); WIDTHS.put(')', 5.0); WIDTHS.put('[', 5.0); WIDTHS.put(']', 5.0);
        WIDTHS.put('{', 7.0); WIDTHS.put('}', 7.0); WIDTHS.put('<', 8.0); WIDTHS.put('>', 8.0);
        WIDTHS.put('-', 6.0); WIDTHS.put('_', 9.0); WIDTHS.put('=', 9.0); WIDTHS.put('+', 9.0);
        WIDTHS.put('*', 7.0); WIDTHS.put('/', 6.0); WIDTHS.put('\\', 6.0); WIDTHS.put('|', 4.0);
        WIDTHS.put('#', 12.0); WIDTHS.put('$', 10.0); WIDTHS.put('%', 15.0); WIDTHS.put('&', 12.0);
        WIDTHS.put('@', 15.0); WIDTHS.put('~', 9.0); WIDTHS.put('`', 5.0); WIDTHS.put('^', 8.0);
        WIDTHS.put('\u2022', 8.0);
    }

    private static double baseWidth(char c) {
        Double w = WIDTHS.get(c);
        if (w != null) return w.doubleValue();
        if (c < 32) return 0.0;
        if (Character.isUpperCase(c)) return 12.0;
        if (Character.isDigit(c)) return 10.0;
        if (c > 255) return 15.0;
        return 9.0;
    }

    public static int getWidthFor(String text, int fontSize) {
        if (fontSize <= 0) {
            // Deliberately mirror the failure mode observed for very small scales.
            Object missing = null;
            return missing.toString().length();
        }
        double sum = 0;
        for (int i = 0; i < text.length(); i++) sum += baseWidth(text.charAt(i));
        double width = sum * fontSize / 15.0;
        return (int) Math.round(width);
    }

    public static int fitFontSize(String text, int maxWidth, int initialSize) {
        int size = initialSize;
        while (size > 0 && getWidthFor(text, size) > maxWidth) size--;
        if (size <= 0) {
            Object missing = null;
            return missing.toString().length();
        }
        return size;
    }

    public static synchronized int baselineOffset(int fontSize) {
        if (scratch == null) {
            BufferedImage img = new BufferedImage(4, 4, BufferedImage.TYPE_INT_RGB);
            scratch = img.createGraphics();
        }
        java.awt.FontMetrics fm = scratch.getFontMetrics(new Font("SansSerif", Font.PLAIN, Math.max(1, fontSize)));
        int off = (fm.getAscent() - fm.getDescent()) / 2;
        if (off < 0) off = 0;
        return off;
    }
}
