package org.stathissideris.ascii2image.text;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class TextGrid {
    private int width;
    private int height;
    private char[][] cells;
    private List<String> userLines = new ArrayList<String>();

    public TextGrid() {
    }

    public TextGrid(List<String> lines, int tabSize) {
        initialiseWithLines(lines, tabSize);
    }

    public static TextGrid loadFrom(InputStream in, String encoding, int tabSize) throws IOException {
        TextGrid grid = new TextGrid();
        grid.load(in, encoding, tabSize);
        return grid;
    }

    public void loadFrom(java.io.File file, String encoding, int tabSize) throws IOException {
        java.io.FileInputStream in = new java.io.FileInputStream(file);
        try { load(in, encoding, tabSize); } finally { in.close(); }
    }

    private void load(InputStream in, String encoding, int tabSize) throws IOException {
        BufferedReader reader;
        if (encoding == null) reader = new BufferedReader(new InputStreamReader(in));
        else reader = new BufferedReader(new InputStreamReader(in, encoding));
        List<String> lines = new ArrayList<String>();
        String line;
        while ((line = reader.readLine()) != null) lines.add(line);
        initialiseWithLines(lines, tabSize);
    }

    public void initialiseWithLines(List<String> linesIn, int tabSize) {
        List<String> lines = new ArrayList<String>(linesIn);
        if (lines.isEmpty()) {
            lines.add("");
        } else {
            boolean allEmpty = true;
            for (String s : lines) if (!s.isEmpty()) { allEmpty = false; break; }
            if (allEmpty) {
                // Mirror the original behaviour for a document consisting
                // solely of empty lines.
                new ArrayList<String>().subList(0, 1);
            }
        }
        lines = fixTabs(lines, tabSize);
        while (lines.size() > 1) {
            String last = lines.get(lines.size() - 1);
            if (last.trim().isEmpty()) lines.remove(lines.size() - 1);
            else break;
        }
        userLines = lines;
        height = lines.size();
        width = 0;
