        boolean inside = false;
        ArrayList<Pt> p = ci.originalPoints;
        for (int i = 0, j = p.size() - 1; i < p.size(); j = i++) {
            double xi = p.get(i).x, yi = p.get(i).y, xj = p.get(j).x, yj = p.get(j).y;
            boolean intersect = ((yi > py) != (yj > py)) && (px < (xj - xi) * (py - yi) / (yj - yi) + xi);
            if (intersect) inside = !inside;
        }
        return inside;
    }

    private void assignMarkupsAndSeparate() {
        for (Markup m : markups) {
            ClosedInfo best = null;
            int px = centerX(m.x), py = centerY(m.y);
            for (ClosedInfo ci : closed) {
                if (pointInClosed(ci, px, py)) {
                    if (best == null || ci.area < best.area) best = ci;
                }
            }
            if (best != null) {
                if (m.isColor) best.fill = m.color;
                else best.type = m.type;
            }
        }
        if (!options.performSeparation() || closed.size() < 2) return;
        // insert points lying on edges
        for (ClosedInfo ci : closed) {
            ArrayList<Pt> newPoints = new ArrayList<Pt>();
            int n = ci.points.size();
            for (int i = 0; i < n; i++) {
                Pt a = ci.points.get(i);
                Pt b = ci.points.get((i + 1) % n);
                newPoints.add(a);
                ArrayList<Pt> mids = new ArrayList<Pt>();
                for (ClosedInfo other : closed) {
                    if (other == ci) continue;
                    for (Pt p : other.points) {
                        if ((p.x == a.x && p.y == a.y) || (p.x == b.x && p.y == b.y)) continue;
                        if (onSegment(p, a, b)) {
                            boolean exists = false;
                            for (Pt q : mids) if (q.x == p.x && q.y == p.y) exists = true;
                            if (!exists) mids.add(new Pt(p.x, p.y, p.cx, p.cy));
                        }
                    }
                }
                // sort mids by distance from a
                for (int u = 0; u < mids.size(); u++) for (int v = u + 1; v < mids.size(); v++) {
                    double du = dist2(a, mids.get(u)), dv = dist2(a, mids.get(v));
                    if (dv < du) { Pt tmp = mids.get(u); mids.set(u, mids.get(v)); mids.set(v, tmp); }
                }
                newPoints.addAll(mids);
            }
            ci.points = newPoints;
        }
        float sep = 2.0f * options.scale;
        int nc = closed.size();
        float[][] shiftX = new float[nc][];
        float[][] shiftY = new float[nc][];
        for (int idx = 0; idx < nc; idx++) {
            shiftX[idx] = new float[closed.get(idx).points.size()];
            shiftY[idx] = new float[closed.get(idx).points.size()];
        }
        for (int idx = 0; idx < nc; idx++) {
            ClosedInfo ci = closed.get(idx);
            int n = ci.points.size();
            for (int i = 0; i < n; i++) {
                Pt a = ci.points.get(i), b = ci.points.get((i + 1) % n);
                boolean shared = false;
                for (int j = 0; j < nc && !shared; j++) {
                    if (j == idx) continue;
                    ClosedInfo o = closed.get(j);
                    int m = o.points.size();
                    for (int k = 0; k < m; k++) {
                        Pt c = o.points.get(k), d = o.points.get((k + 1) % m);
                        if ((a.x == c.x && a.y == c.y && b.x == d.x && b.y == d.y) ||
                            (a.x == d.x && a.y == d.y && b.x == c.x && b.y == c.y)) { shared = true; break; }
                    }
                }
                if (!shared) continue;
                double dx = b.x - a.x, dy = b.y - a.y;
                double len = Math.hypot(dx, dy);
                if (len == 0) continue;
                double ux = dx / len, uy = dy / len;
                double lx = uy, ly = -ux; // left of travel in screen coordinates
                float ox = (float) (lx * sep), oy = (float) (ly * sep);
                if (ox != 0) { shiftX[idx][i] = ox; shiftX[idx][(i + 1) % n] = ox; }
                if (oy != 0) { shiftY[idx][i] = oy; shiftY[idx][(i + 1) % n] = oy; }
            }
        }
        for (int idx = 0; idx < nc; idx++) {
            ClosedInfo ci = closed.get(idx);
            for (int i = 0; i < ci.points.size(); i++) {
                Pt p = ci.points.get(i);
                p.x += shiftX[idx][i];
                p.y += shiftY[idx][i];
            }
            // remove collinear unshifted points
            boolean again = true;
            while (again && ci.points.size() > 3) {
                again = false;
                for (int i = 0; i < ci.points.size(); i++) {
                    Pt prev = ci.points.get((i - 1 + ci.points.size()) % ci.points.size());
                    Pt cur = ci.points.get(i);
                    Pt next = ci.points.get((i + 1) % ci.points.size());
                    double cross = (cur.x - prev.x) * (next.y - cur.y) - (cur.y - prev.y) * (next.x - cur.x);
                    if (cross == 0 && shiftX[idx][i] == 0 && shiftY[idx][i] == 0) {
                        // keep points that are line junctions on a straight edge if they are corner cells?
                        if (cur.cx >= 0 && (ch(cur.cx, cur.cy) == '/' || ch(cur.cx, cur.cy) == '\\')) continue;
                        ci.points.remove(i); again = true; break;
                    }
                }
            }
        }
    }

    private boolean onSegment(Pt p, Pt a, Pt b) {
        double cross = (p.x - a.x) * (b.y - a.y) - (p.y - a.y) * (b.x - a.x);
        if (Math.abs(cross) > 0.01) return false;
        double dot = (p.x - a.x) * (p.x - b.x) + (p.y - a.y) * (p.y - b.y);
        return dot <= 0.01;
    }
    private double dist2(Pt a, Pt b) { double dx = a.x - b.x, dy = a.y - b.y; return dx * dx + dy * dy; }

    // ---------- open shapes ----------

    private HashSet<Long> closedEdges() {
        HashSet<Long> set = new HashSet<Long>();
        // recompute from face cycles is not retained; instead mark edges whose
        // both directed faces were interior is complex. Caller recomputes by
        // checking whether an undirected edge lies on any closed polygon.
        for (ClosedInfo ci : closed) {
            // original points trace boundary along grid cells; mark grid edges
            // by walking between successive original vertices (axis aligned)
            int n = ci.originalPoints.size();
            for (int i = 0; i < n; i++) {
                Pt a = ci.originalPoints.get(i), b = ci.originalPoints.get((i + 1) % n);
                if (a.cx < 0 || b.cx < 0) continue;
                int x = a.cx, y = a.cy;
                int steps = Math.abs(b.cx - a.cx) + Math.abs(b.cy - a.cy);
                int sx = Integer.signum(b.cx - a.cx), sy = Integer.signum(b.cy - a.cy);
                for (int s = 0; s < steps; s++) {
                    int x2 = x + sx, y2 = y + sy;
                    long key = edgeKey(x, y, x2, y2);
                    set.add(key);
                    x = x2; y = y2;
                }
            }
        }
        return set;
    }

    private long edgeKey(int x1, int y1, int x2, int y2) {
        int a = y1 * gw + x1, b = y2 * gw + x2;
        int lo = Math.min(a, b), hi = Math.max(a, b);
        return (((long) lo) << 32) | hi;
    }

    private void buildOpenShapes() {
        HashSet<Long> usedByClosed = closedEdges();
        HashSet<Long> used = new HashSet<Long>();
        // remaining adjacency degree
        // walks starting at breakpoints
        for (int sy = 0; sy < gh; sy++) for (int sx = 0; sx < gw; sx++) {
            if (!node[sy][sx]) continue;
            int deg = remainingDegree(sx, sy, usedByClosed);
            if (deg == 2 || deg == 0) continue;
            for (int d = 0; d < 4; d++) {
                if (!edgeExists(sx, sy, d)) continue;
                int nx = sx + DX[d], ny = sy + DY[d];
                long key = edgeKey(sx, sy, nx, ny);
                if (usedByClosed.contains(key) || used.contains(key)) continue;
                ArrayList<int[]> cells = walkOpen(sx, sy, nx, ny, usedByClosed, used);
                if (cells.size() >= 2) addOpenShape(cells);
            }
        }
        // cycles / remaining components
        for (int sy = 0; sy < gh; sy++) for (int sx = 0; sx < gw; sx++) {
            if (!node[sy][sx]) continue;
            for (int d = 0; d < 4; d++) {
                if (!edgeExists(sx, sy, d)) continue;
                int nx = sx + DX[d], ny = sy + DY[d];
                long key = edgeKey(sx, sy, nx, ny);
                if (usedByClosed.contains(key) || used.contains(key)) continue;
                ArrayList<int[]> cells = walkOpen(sx, sy, nx, ny, usedByClosed, used);
                if (cells.size() >= 2) addOpenShape(cells);
            }
        }
        // isolated single line cells
        for (int y = 0; y < gh; y++) for (int x = 0; x < gw; x++) {
            if (!node[y][x]) continue;
            if (remainingDegree(x, y, usedByClosed) != 0) continue;
            char c = ch(x, y);
            if (c != '-' && c != '|') continue;
            // check it did not participate in a closed shape (e.g. as degenerate)
            ArrayList<int[]> single = new ArrayList<int[]>();
            single.add(new int[]{x, y});
            addIsolatedShape(x, y, c);
        }
    }

    private int remainingDegree(int x, int y, HashSet<Long> usedByClosed) {
        int deg = 0;
        for (int d = 0; d < 4; d++) {
            if (!edgeExists(x, y, d)) continue;
            int nx = x + DX[d], ny = y + DY[d];
            if (usedByClosed.contains(edgeKey(x, y, nx, ny))) continue;
            deg++;
        }
        return deg;
    }

    private ArrayList<int[]> walkOpen(int sx, int sy, int nx, int ny, HashSet<Long> usedByClosed, HashSet<Long> used) {
        ArrayList<int[]> cells = new ArrayList<int[]>();
        cells.add(new int[]{sx, sy});
        int px = sx, py = sy, cx = nx, cy = ny;
        used.add(edgeKey(px, py, cx, cy));
        while (true) {
            cells.add(new int[]{cx, cy});
            if (remainingDegree(cx, cy, usedByClosed) != 2) break;
            int nxtX = -1, nxtY = -1;
            for (int d = 0; d < 4; d++) {
                if (!edgeExists(cx, cy, d)) continue;
                int ax = cx + DX[d], ay = cy + DY[d];
                if (ax == px && ay == py) continue;
                if (usedByClosed.contains(edgeKey(cx, cy, ax, ay))) continue;
                nxtX = ax; nxtY = ay; break;
            }
            if (nxtX < 0) break;
            long key = edgeKey(cx, cy, nxtX, nxtY);
            if (used.contains(key)) break;
            used.add(key);
            px = cx; py = cy; cx = nxtX; cy = nxtY;
            if (cells.size() > gw * gh + 10) break;
        }
        return cells;
    }

    private void addIsolatedShape(int x, int y, char c) {
        Path2D.Double path = new Path2D.Double();
        int cxp = centerX(x), cyp = centerY(y);
        boolean hasArrowW = x > 0 && arrowCell[y][x - 1];
        boolean hasArrowE = x + 1 < gw && arrowCell[y][x + 1];
        boolean hasArrowN = y > 0 && arrowCell[y - 1][x];
        boolean hasArrowS = y + 1 < gh && arrowCell[y + 1][x];
        if (c == '-') {
            double x1 = hasArrowW ? centerX(x - 1) : leftX(x);
            double x2 = hasArrowE ? centerX(x + 1) : (leftX(x) + cellW - 1);
            path.moveTo(x1, cyp); path.lineTo(x2, cyp);
        } else {
            double y1 = hasArrowN ? centerY(y - 1) : topY(y);
            double y2 = hasArrowS ? centerY(y + 1) : (topY(y) + cellH - 1);
            path.moveTo(cxp, y1); path.lineTo(cxp, y2);
        }
        DiagramShape ds = new DiagramShape();
        ds.awtShape = path; ds.closed = false; ds.dashed = false;
        openRenderShapes.add(ds);
    }

    private void addOpenShape(ArrayList<int[]> cells) {
        // simplify collinear points
        ArrayList<Pt> pts = new ArrayList<Pt>();
        for (int i = 0; i < cells.size(); i++) {
            int[] cur = cells.get(i);
            boolean keep;
            if (i == 0 || i == cells.size() - 1) keep = true;
            else {
                int[] prev = cells.get(i - 1), next = cells.get(i + 1);
                keep = dirBetween(prev, cur) != dirBetween(cur, next) || ch(cur[0], cur[1]) == '*' || ch(cur[0], cur[1]) == '/' || ch(cur[0], cur[1]) == '\\';
            }
            if (keep) pts.add(new Pt(centerX(cur[0]), centerY(cur[1]), cur[0], cur[1]));
        }
        // arrow extensions
        if (!cells.isEmpty()) {
            int[] first = cells.get(0);
            int[] last = cells.get(cells.size() - 1);
            // first
            int ad = arrowNeighbourDirection(first, cells.size() > 1 ? cells.get(1) : null, true);
            if (ad >= 0) {
                int ax = first[0] + DX[ad], ay = first[1] + DY[ad];
                pts.add(0, new Pt(centerX(ax), centerY(ay), ax, ay));
            }
            ad = arrowNeighbourDirection(last, cells.size() > 1 ? cells.get(cells.size() - 2) : null, false);
            if (ad >= 0) {
                int ax = last[0] + DX[ad], ay = last[1] + DY[ad];
                pts.add(new Pt(centerX(ax), centerY(ay), ax, ay));
            }
        }
        boolean dashed = false;
        for (int[] c : cells) {
            char cc = ch(c[0], c[1]);
            if (cc == '=' || cc == ':') dashed = true;
        }
        DiagramShape ds = new DiagramShape();
        ds.awtShape = buildOpenPath(pts);
        ds.closed = false; ds.dashed = dashed;
        openRenderShapes.add(ds);
    }

    private int arrowNeighbourDirection(int[] cell, int[] other, boolean atStart) {
        // prefer continuation direction
        int pref = -1;
        if (other != null) {
            if (atStart) pref = dirBetween(cell, other); // direction from endpoint to next; continuation is reverse
            else pref = dirBetween(other, cell);
            // for start, arrow should be opposite to pref; for end, arrow is same as pref
            int want = atStart ? ((pref + 2) % 4) : pref;
            int ax = cell[0] + DX[want], ay = cell[1] + DY[want];
            if (ax >= 0 && ay >= 0 && ax < gw && ay < gh && arrowCell[ay][ax]) return want;
        }
        for (int d = 0; d < 4; d++) {
            int ax = cell[0] + DX[d], ay = cell[1] + DY[d];
            if (ax >= 0 && ay >= 0 && ax < gw && ay < gh && arrowCell[ay][ax]) return d;
        }
        return -1;
    }

    private Path2D.Double buildOpenPath(ArrayList<Pt> pts) {
        Path2D.Double path = new Path2D.Double();
        if (pts.isEmpty()) return path;
        // determine round points
        int n = pts.size();
        path.moveTo(pts.get(0).x, pts.get(0).y);
        for (int i = 1; i < n; i++) {
            Pt prev = pts.get(i - 1), cur = pts.get(i);
            boolean isLast = i == n - 1;
            if (!isLast && isRoundPt(cur)) {
                Pt next = pts.get(i + 1);
                Pt in = offsetTowards(cur, prev), out = offsetTowards(cur, next);
                path.lineTo(in.x, in.y);
                path.quadTo(cur.x, cur.y, out.x, out.y);
            } else {
                path.lineTo(cur.x, cur.y);
            }
        }
        return path;
    }

    private boolean isRoundPt(Pt p) {
        if (options.roundCorners) return true;
        if (p.cx < 0 || p.cy < 0) return false;
        char c = ch(p.cx, p.cy);
        return c == '/' || c == '\\';
    }

    private Pt offsetTowards(Pt from, Pt towards) {
        double dx = towards.x - from.x, dy = towards.y - from.y;
        double len = Math.hypot(dx, dy);
        if (len == 0) return new Pt(from.x, from.y, from.cx, from.cy);
        double off = (Math.abs(dx) > Math.abs(dy)) ? cellW / 2.0 : cellH / 2.0;
        if (off > len) off = len;
        return new Pt((float) (from.x + dx / len * off), (float) (from.y + dy / len * off), from.cx, from.cy);
    }

    // ---------- arrows and markers ----------

    private void buildArrowsAndMarkers() {
        double dx = cellW / 2.0, dy = cellH / 2.0;
        for (int y = 0; y < gh; y++) for (int x = 0; x < gw; x++) {
            if (arrowCell[y][x]) {
                int cx = centerX(x), cy = centerY(y);
                char c = ch(x, y);
                Path2D.Double p = new Path2D.Double();
                if (c == '<') {
                    p.moveTo(cx + dx, cy - dy); p.lineTo(cx - dx, cy); p.lineTo(cx + dx, cy + dy); p.closePath();
                } else if (c == '>') {
                    p.moveTo(cx - dx, cy - dy); p.lineTo(cx + dx, cy); p.lineTo(cx - dx, cy + dy); p.closePath();
                } else if (c == 'v') {
                    p.moveTo(cx - dx, cy - dy); p.lineTo(cx, cy + dy); p.lineTo(cx + dx, cy - dy); p.closePath();
                } else { // ^
                    p.moveTo(cx, cy - dy); p.lineTo(cx - dx, cy + dy); p.lineTo(cx + dx, cy + dy); p.closePath();
                }
                DiagramShape ds = new DiagramShape();
                ds.awtShape = p; ds.fill = Color.black; ds.closed = true;
                arrowShapes.add(ds);
            }
            if (ch(x, y) == '*' && node[y][x]) {
                double r = 3.5 * options.scale;
                if (r <= 0) r = 0.5;
                Ellipse2D.Double e = new Ellipse2D.Double(centerX(x) - r, centerY(y) - r, 2 * r, 2 * r);
                DiagramShape ds = new DiagramShape();
                ds.awtShape = e; ds.fill = Color.white; ds.closed = true;
                markerShapes.add(ds);
            }
        }
    }

    // ---------- texts ----------

    private static class Seg {
        int x, y, start, end, realEnd;
        String text;
        boolean bullet;
    }

    private void buildTexts() {
        ArrayList<Seg> segs = new ArrayList<Seg>();
        for (int y = 0; y < gh; y++) {
            // bullet starts
            boolean[] bullet = new boolean[gw];
            for (int x = 0; x < gw; x++) {
                char c = ch(x, y);
                if (c != 'o' && c != '*') continue;
                if (c == '*' && node[y][x]) continue;
                boolean prevBlank = x == 0 || blankForText[y][x - 1];
                if (!prevBlank) continue;
                if (x + 2 < gw && blankForText[y][x + 1] && !blankForText[y][x + 2]) bullet[x] = true;
            }
            int x = 0;
            while (x < gw) {
                if (!bullet[x] && blankForText[y][x]) { x++; continue; }
                Seg seg = new Seg();
                seg.y = y; seg.start = x; seg.bullet = bullet[x];
                StringBuilder sb = new StringBuilder();
                int p;
                int lastNonBlank;
                if (bullet[x]) {
                    sb.append('\u2022');
                    lastNonBlank = x;
                    p = x + 2;
                } else {
                    sb.append(ch(x, y));
                    lastNonBlank = x;
                    p = x + 1;
                }
                while (p < gw) {
                    if (bullet[p]) break;
                    if (!blankForText[y][p]) {
                        sb.append(ch(p, y));
                        lastNonBlank = p;
                        p++;
                    } else {
                        if (p + 1 < gw && !blankForText[y][p + 1] && !bullet[p + 1]) {
                            sb.append(' ');
                            p++;
                        } else break;
                    }
                }
                seg.text = sb.toString();
                seg.realEnd = lastNonBlank;
                seg.end = lastNonBlank;
                if (seg.text.length() == 1) {
                    seg.text = seg.text + " ";
                    seg.end = seg.start + 1;
                }
                segs.add(seg);
                x = lastNonBlank + 1;
            }
        }
        // grouping by adjacency (intervals overlapping on consecutive rows)
        int[] parent = new int[segs.size()];
        for (int i = 0; i < parent.length; i++) parent[i] = i;
        for (int i = 0; i < segs.size(); i++) for (int j = i + 1; j < segs.size(); j++) {
            Seg a = segs.get(i), b = segs.get(j);
            if (Math.abs(a.y - b.y) == 1 && Math.max(a.start, b.start) <= Math.min(a.realEnd, b.realEnd)) {
                int ra = find(parent, i), rb = find(parent, j);
                if (ra != rb) parent[rb] = ra;
            }
        }
        HashMap<Integer, Integer> groupRows = new HashMap<Integer, Integer>();
        for (int i = 0; i < segs.size(); i++) {
            int r = find(parent, i);
            Integer cnt = groupRows.get(r);
            groupRows.put(r, cnt == null ? 1 : cnt + 1);
        }
        // note: counting segments, but a group with 2 segments on same row is not multiline;
        // recompute distinct rows
        HashMap<Integer, HashSet<Integer>> rowsInGroup = new HashMap<Integer, HashSet<Integer>>();
        for (int i = 0; i < segs.size(); i++) {
            int r = find(parent, i);
            HashSet<Integer> set = rowsInGroup.get(r);
            if (set == null) { set = new HashSet<Integer>(); rowsInGroup.put(r, set); }
            set.add(segs.get(i).y);
        }
        int initialSize = Math.round(15.0f * options.scale);
        for (Seg seg : segs) {
            int extentCells = seg.end - seg.start + 1;
            if (extentCells < 1) extentCells = 1;
            int fontSize = FontMeasurer.fitFontSize(seg.text, extentCells * cellW, initialSize);
            int yPix = centerY(seg.y) + FontMeasurer.baselineOffset(fontSize);
            int root = find(parent, segs.indexOf(seg));
            boolean multiline = rowsInGroup.get(root) != null && rowsInGroup.get(root).size() > 1;
            int xPix;
            if (multiline) {
                xPix = leftX(seg.start);
            } else {
                double centre = leftX(seg.start) + extentCells * cellW / 2.0;
                int tw = FontMeasurer.getWidthFor(seg.text, fontSize);
                xPix = (int) (centre - tw / 2.0);
            }
            Color col = textColorFor(seg);
            TextInfo ti = new TextInfo();
            ti.text = seg.text; ti.x = xPix; ti.y = yPix; ti.fontSize = fontSize; ti.color = col;
            texts.add(ti);
        }
    }

    private int find(int[] p, int i) {
        while (p[i] != i) { p[i] = p[p[i]]; i = p[i]; }
        return i;
    }

    private Color textColorFor(Seg seg) {
        int px = centerX(seg.start), py = centerY(seg.y);
        ClosedInfo best = null;
        for (ClosedInfo ci : closed) {
            if (pointInClosedForText(ci, px, py)) {
                if (best == null || ci.area < best.area) best = ci;
            }
        }
        if (best != null) {
            Color f = best.fill;
            int max = Math.max(f.getRed(), Math.max(f.getGreen(), f.getBlue()));
            return max < 200 ? Color.white : Color.black;
        }
        // arrow adjacency / arrow inside segment
        for (int cx = seg.start; cx <= seg.realEnd; cx++) {
            if (cx >= 0 && cx < gw && seg.y >= 0 && seg.y < gh && arrowCell[seg.y][cx]) return Color.white;
            if (cx >= 0 && cx < gw) {
                if (seg.y > 0 && arrowCell[seg.y - 1][cx]) return Color.white;
                if (seg.y + 1 < gh && arrowCell[seg.y + 1][cx]) return Color.white;
            }
        }
        return Color.black;
    }

    private boolean pointInClosedForText(ClosedInfo ci, int px, int py) {
        // use original (pre-separation) points
        boolean inside = false;
        ArrayList<Pt> p = ci.originalPoints;
        if (p.size() < 3) return false;
        for (int i = 0, j = p.size() - 1; i < p.size(); j = i++) {
            double xi = p.get(i).x, yi = p.get(i).y, xj = p.get(j).x, yj = p.get(j).y;
            boolean intersect = ((yi > py) != (yj > py)) && (px < (xj - xi) * (py - yi) / (yj - yi) + xi);
            if (intersect) inside = !inside;
        }
        return inside;
    }

    // ---------- render shape construction ----------

    private void buildRenderShapes() {
        for (ClosedInfo ci : closed) {
            DiagramShape ds = new DiagramShape();
            ds.closed = true; ds.dashed = ci.dashed; ds.fill = ci.fill; ds.type = ci.type;
            ds.storage = ci.type == TYPE_STORAGE;
            ds.awtShape = buildClosedAwtShape(ci);
            renderShapes.add(ds);
        }
    }

    private Shape buildClosedAwtShape(ClosedInfo ci) {
        if (ci.type != TYPE_NORMAL) return buildSpecialShape(ci);
        ArrayList<Pt> pts = ci.points;
        boolean anyRound = false;
        for (Pt p : pts) if (isRoundPt(p)) { anyRound = true; break; }
        if (!anyRound) {
            Path2D.Double path = new Path2D.Double();
            for (int i = 0; i < pts.size(); i++) {
                if (i == 0) path.moveTo(pts.get(i).x, pts.get(i).y);
                else path.lineTo(pts.get(i).x, pts.get(i).y);
            }
            path.closePath();
            return path;
        }
        // rounded polygon, starting just before first point
        Path2D.Double path = new Path2D.Double();
        int n = pts.size();
        Pt first = pts.get(0);
        Pt prev = pts.get(n - 1);
        Pt startPt = isRoundPt(first) ? offsetTowards(first, prev) : first;
        path.moveTo(startPt.x, startPt.y);
        for (int i = 0; i < n; i++) {
            Pt cur = pts.get(i);
            Pt next = pts.get((i + 1) % n);
            Pt prv = pts.get((i - 1 + n) % n);
            if (isRoundPt(cur)) {
                if (i != 0) {
                    Pt in = offsetTowards(cur, prv);
                    path.lineTo(in.x, in.y);
                }
                Pt out = offsetTowards(cur, next);
                path.quadTo(cur.x, cur.y, out.x, out.y);
            } else {
                path.lineTo(cur.x, cur.y);
            }
        }
        path.closePath();
        return path;
    }

    private Shape buildSpecialShape(ClosedInfo ci) {
        float minX = Float.MAX_VALUE, minY = Float.MAX_VALUE, maxX = -Float.MAX_VALUE, maxY = -Float.MAX_VALUE;
        for (Pt p : ci.points) {
            if (p.x < minX) minX = p.x; if (p.y < minY) minY = p.y;
            if (p.x > maxX) maxX = p.x; if (p.y > maxY) maxY = p.y;
        }
        int x1 = (int) minX, y1 = (int) minY, x2 = (int) maxX, y2 = (int) maxY;
        int w = x2 - x1, h = y2 - y1;
        int midX = (x1 + x2) / 2, midY = (y1 + y2) / 2;
        Path2D.Double path = new Path2D.Double();
        switch (ci.type) {
            case TYPE_DOCUMENT: {
                int amp = h / 8;
                int cox = w / 6;
                path.moveTo(x1, y1);
                path.lineTo(x2, y1);
                path.lineTo(x2, y2);
                path.quadTo(midX + cox, y2 - amp, midX, y2);
                path.quadTo(midX - cox, y2 + amp, x1, y2);
                path.closePath();
                return path;
            }
            case TYPE_STORAGE: {
                int cox = w / 6;
                int topOff = cellH / 2;
                int botOff = cellW;
                path.moveTo(x1, y1);
                path.curveTo(x1 + cox, y1 + topOff, x2 - cox, y1 + topOff, x2, y1);
                path.curveTo(x2 - cox, y1 - topOff, x1 + cox, y1 - topOff, x1, y1);
                path.moveTo(x1, y1);
                path.lineTo(x1, y2);
                path.curveTo(x1 + cox, y2 + botOff, x2 - cox, y2 + botOff, x2, y2);
                path.lineTo(x2, y1);
                return path;
            }
            case TYPE_ELLIPSE:
                return new Ellipse2D.Double(x1, y1, w, h);
            case TYPE_DECISION: {
                path.moveTo(x1, midY); path.lineTo(midX, y1); path.lineTo(x2, midY); path.lineTo(midX, y2); path.closePath();
                return path;
            }
            default: {
                double off = options.fixedSlope ? (h / 8.0) : (cellW / 2.0);
                if (ci.type == TYPE_TRAPEZOID) {
                    path.moveTo(x1 + off, y1); path.lineTo(x2 - off, y1); path.lineTo(x2 + off, y2); path.lineTo(x1 - off, y2); path.closePath();
                } else if (ci.type == TYPE_IO) {
                    path.moveTo(x1 + off, y1); path.lineTo(x2 + off, y1); path.lineTo(x2 - off, y2); path.lineTo(x1 - off, y2); path.closePath();
                } else if (ci.type == TYPE_MANUAL) {
                    path.moveTo(x1 - off, y1); path.lineTo(x2 + off, y1); path.lineTo(x2 - off, y2); path.lineTo(x1 + off, y2); path.closePath();
                } else {
                    path.moveTo(x1, y1); path.lineTo(x2, y1); path.lineTo(x2, y2); path.lineTo(x1, y2); path.closePath();
                }
                return path;
            }
        }
    }

    // ---------- rendering (PNG) ----------

    public BufferedImage renderToImage() {
        Color bg = options.getBackgroundColor();
        int imgType = options.hasAlphaBackground() ? BufferedImage.TYPE_INT_ARGB : BufferedImage.TYPE_INT_RGB;
        BufferedImage image = new BufferedImage(width, height, imgType);
        Graphics2D g = image.createGraphics();
        setupGraphics(g);
        if (!options.isBackgroundTransparent()) {
            g.setColor(bg);
            g.fillRect(0, 0, width, height);
        }
        if (options.dropShadows()) drawShadows(g);
        // closed shapes
        for (DiagramShape ds : renderShapes) drawClosed(g, ds);
        for (DiagramShape ds : openRenderShapes) drawOpen(g, ds);
        for (DiagramShape ds : arrowShapes) {
            g.setColor(Color.black);
            g.fill(ds.awtShape);
        }
        for (DiagramShape ds : markerShapes) {
            g.setColor(Color.white);
            g.fill(ds.awtShape);
            g.setColor(Color.black);
            setStrokeSolid(g);
            g.draw(ds.awtShape);
        }
        drawTexts(g);
        if (options.debug) drawDebugGrid(g);
        g.dispose();
        return image;
    }

    private void setupGraphics(Graphics2D g) {
        if (options.noAntialias) {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
        } else {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        }
    }

    private void setStrokeSolid(Graphics2D g) {
        g.setStroke(new BasicStroke(options.scale, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
    }
    private void setStrokeDashed(Graphics2D g) {
        float dash = (int) (5 * options.scale);
        if (dash <= 0) dash = 1;
        g.setStroke(new BasicStroke(options.scale, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 0, new float[]{dash, dash}, 0));
    }

    private void drawClosed(Graphics2D g, DiagramShape ds) {
        if (ds.storage) {
            g.setColor(ds.fill);
            g.fill(ds.awtShape);
            g.setColor(Color.white);
            setStrokeSolid(g);
            g.draw(ds.awtShape);
            g.setColor(Color.black);
            g.draw(ds.awtShape);
            return;
        }
        if (ds.dashed) {
            g.setColor(Color.black);
            setStrokeDashed(g);
            g.draw(ds.awtShape);
            return;
        }
        g.setColor(ds.fill);
        g.fill(ds.awtShape);
        g.setColor(Color.black);
        setStrokeSolid(g);
        g.draw(ds.awtShape);
    }

    private void drawOpen(Graphics2D g, DiagramShape ds) {
        g.setColor(Color.black);
        if (ds.dashed) setStrokeDashed(g); else setStrokeSolid(g);
        g.draw(ds.awtShape);
    }

    private void drawTexts(Graphics2D g) {
        for (TextInfo t : texts) {
            g.setColor(t.color);
            g.setFont(new java.awt.Font("SansSerif", java.awt.Font.PLAIN, t.fontSize));
            g.drawString(t.text, t.x, t.y);
        }
    }

    private void drawDebugGrid(Graphics2D g) {
        if (cellW <= 0 || cellH <= 0) return;
        Object oldAA = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        g.setStroke(new BasicStroke(1));
        g.setColor(new Color(170, 170, 170));
        for (int x = 0; x < width; x += cellW) g.drawLine(x, 0, x, height);
        for (int y = 0; y < height; y += cellH) g.drawLine(0, y, width, y);
        if (oldAA != null) g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAA);
    }

    private void drawShadows(Graphics2D g) {
        ArrayList<DiagramShape> shadowShapes = new ArrayList<DiagramShape>();
        for (DiagramShape ds : renderShapes) if (!ds.dashed) shadowShapes.add(ds);
        if (shadowShapes.isEmpty() || width <= 0 || height <= 0) return;
        BufferedImage shadow = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D sg = shadow.createGraphics();
        setupGraphics(sg);
        sg.setColor(Color.black);
        for (DiagramShape ds : shadowShapes) sg.fill(ds.awtShape);
        sg.dispose();
        int r = Math.max(1, (int) Math.round(3 * options.scale));
        int size = 2 * r + 1;
        float[] kernelData = new float[size * size];
        double sigma = Math.max(0.8, r / 1.5);
        double sum = 0;
        for (int i = 0; i < size; i++) for (int j = 0; j < size; j++) {
            double dx = i - r, dy = j - r;
            double v = Math.exp(-(dx * dx + dy * dy) / (2 * sigma * sigma));
            kernelData[j * size + i] = (float) v;
            sum += v;
        }
        for (int i = 0; i < kernelData.length; i++) kernelData[i] = (float) (kernelData[i] / sum);
        Kernel kernel = new Kernel(size, size, kernelData);
        ConvolveOp op = new ConvolveOp(kernel, ConvolveOp.EDGE_NO_OP, null);
        BufferedImage blurred = op.filter(shadow, null);
        int offset = Math.max(1, (int) Math.round(3 * options.scale));
        java.awt.Composite old = g.getComposite();
        g.setComposite(java.awt.AlphaComposite.SrcOver.derive(0.4f));
        g.drawImage(blurred, offset, offset, null);
        g.setComposite(old);
    }

    // ---------- SVG ----------

    public String toSVG() {
        StringBuilder sb = new StringBuilder();
        sb.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n");
        sb.append("<svg \n");
        sb.append("    xmlns='http://www.w3.org/2000/svg'\n");
        sb.append("    width='").append(width).append("'\n");
        sb.append("    height='").append(height).append("'\n");
        sb.append("    shape-rendering='geometricPrecision'\n");
        sb.append("    version='1.0'>\n");
        sb.append("  <defs>\n");
        if (options.svgFontUrl != null) {
            sb.append("    <style type='text/css'>\n");
            sb.append("      @font-face {\n");
            sb.append("        font-family: Custom;\n");
            sb.append("        src: url('").append(options.svgFontUrl).append("');\n");
            sb.append("      }\n");
            sb.append("    </style>\n");
        }
        sb.append("    <filter id='f2' x='0' y='0' width='200%' height='200%'>\n");
        sb.append("      <feOffset result='offOut' in='SourceGraphic' dx='5' dy='5' />\n");
        sb.append("      <feGaussianBlur result='blurOut' in='offOut' stdDeviation='3' />\n");
        sb.append("      <feBlend in='SourceGraphic' in2='blurOut' mode='normal' />\n");
        sb.append("    </filter>\n");
        sb.append("  </defs>\n");
        sb.append("  <g stroke-width='1' stroke-linecap='square' stroke-linejoin='round'>\n");
        if (!options.isBackgroundTransparent()) {
            Color bg = options.getBackgroundColor();
            sb.append("    <rect x='0' y='0' width='").append(width).append("' height='").append(height)
              .append("' style='fill: ").append(hexColor(bg)).append("'/>\n");
        }
        for (DiagramShape ds : renderShapes) {
            if (options.dropShadows() && !ds.dashed) {
                sb.append("    <path stroke='gray' fill='gray' filter='url(#f2)' d='").append(pathData(ds.awtShape)).append("' />\n");
            }
            if (ds.storage) {
                sb.append("    <path stroke='white' stroke-width='").append(strokeWidthString()).append("' stroke-linecap='round' stroke-linejoin='round' fill='")
                  .append(fillColorString(ds.fill, true)).append("' d='").append(pathData(ds.awtShape)).append("' />\n");
                sb.append("    <path stroke='#000000' stroke-width='").append(strokeWidthString()).append("' stroke-linecap='round' stroke-linejoin='round' fill='none' d='").append(pathData(ds.awtShape)).append("' />\n");
            } else if (ds.dashed) {
                sb.append("    <path stroke='#000000' stroke-width='").append(strokeWidthString()).append("' stroke-dasharray='").append(dashString()).append("' stroke-miterlimit='0' stroke-linecap='butt' stroke-linejoin='round' fill='none' d='").append(pathData(ds.awtShape)).append("' />\n");
            } else {
                sb.append("    <path stroke='#000000' stroke-width='").append(strokeWidthString()).append("' stroke-linecap='round' stroke-linejoin='round' fill='")
                  .append(fillColorString(ds.fill, false)).append("' d='").append(pathData(ds.awtShape)).append("' />\n");
            }
        }
        for (DiagramShape ds : openRenderShapes) {
            if (ds.dashed) {
                sb.append("    <path stroke='#000000' stroke-width='").append(strokeWidthString()).append("' stroke-dasharray='").append(dashString()).append("' stroke-miterlimit='0' stroke-linecap='butt' stroke-linejoin='round' fill='none' d='").append(pathData(ds.awtShape)).append("' />\n");
            } else {
                sb.append("    <path stroke='#000000' stroke-width='").append(strokeWidthString()).append("' stroke-linecap='round' stroke-linejoin='round' fill='none' d='").append(pathData(ds.awtShape)).append("' />\n");
            }
        }
        for (DiagramShape ds : arrowShapes) {
            sb.append("    <path stroke='none' stroke-width='").append(strokeWidthString()).append("' stroke-linecap='round' stroke-linejoin='round' fill='#000000' d='").append(pathData(ds.awtShape)).append("' />\n");
        }
        for (DiagramShape ds : markerShapes) {
            sb.append("    <path stroke='#000000' stroke-width='").append(strokeWidthString()).append("' stroke-linecap='round' stroke-linejoin='round' fill='#ffffff' d='").append(pathData(ds.awtShape)).append("' />\n");
        }
        String family = options.svgFontUrl != null ? "Custom" : "Courier";
        for (TextInfo t : texts) {
            sb.append("    <text x='").append(t.x).append("' y='").append(t.y).append("' font-family='").append(family)
              .append("' font-size='").append(t.fontSize).append("' stroke='none' fill='").append(t.color == Color.white ? "#ffffff" : "#000000")
              .append("' ><![CDATA[").append(t.text).append("]]></text>\n");
        }
        sb.append("  </g>\n");
        sb.append("</svg>");
        return sb.toString();
    }

    private String strokeWidthString() {
        float w = options.scale;
        long t = (long) (w * 10.0f);
        if (w >= 0) return (t / 10) + "." + Math.abs(t % 10);
        return String.valueOf(w);
    }
    private String dashString() {
        int dash = (int) (5 * options.scale);
        return dash + ".0," + dash + ".0";
    }
    private String hexColor(Color c) {
        return String.format("#%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
    }
    private String fillColorString(Color c, boolean storageFill) {
        if (!storageFill && c.getRed() == 255 && c.getGreen() == 255 && c.getBlue() == 255) return "white";
        return hexColor(c);
    }
    private String pathData(Shape shape) {
        StringBuilder sb = new StringBuilder();
        PathIterator it = shape.getPathIterator(null);
        double[] coords = new double[6];
        while (!it.isDone()) {
            int seg = it.currentSegment(coords);
            switch (seg) {
                case PathIterator.SEG_MOVETO:
                    sb.append("M").append(num(coords[0])).append(" ").append(num(coords[1])).append(" "); break;
                case PathIterator.SEG_LINETO:
                    sb.append("L").append(num(coords[0])).append(" ").append(num(coords[1])).append(" "); break;
                case PathIterator.SEG_QUADTO:
                    sb.append("Q").append(num(coords[0])).append(" ").append(num(coords[1])).append(" ").append(num(coords[2])).append(" ").append(num(coords[3])).append(" "); break;
                case PathIterator.SEG_CUBICTO:
                    sb.append("C").append(num(coords[0])).append(" ").append(num(coords[1])).append(" ").append(num(coords[2])).append(" ").append(num(coords[3])).append(" ").append(num(coords[4])).append(" ").append(num(coords[5])).append(" "); break;
                case PathIterator.SEG_CLOSE:
                    sb.append("z"); break;
            }
            it.next();
        }
        return sb.toString();
    }
    private String num(double v) {
        return Float.toString((float) v);
    }
}
