package org.stathissideris.ascii2image.core;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.stathissideris.ascii2image.graphics.Diagram;
import org.stathissideris.ascii2image.text.TextGrid;

public class HTMLConverter {

    private static class Elem {
        int start;
        int end;
        String id;
        String content;
        String filename;
    }

    public static void convertHTMLFile(String inp, String outArg, ConversionOptions options) {
        String html;
        try {
            FileInputStream in = new FileInputStream(new File(inp));
            try {
                java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
                byte[] buf = new byte[8192];
                int r;
                while ((r = in.read(buf)) >= 0) bos.write(buf, 0, r);
                if (options.encoding != null) html = bos.toString(options.encoding);
                else html = bos.toString(java.nio.charset.Charset.defaultCharset().name());
            } finally { in.close(); }
        } catch (Exception e) {
            System.err.println("Error: cannot read file " + inp);
            return;
        }

        String dest;
        if (outArg != null) dest = outArg;
        else dest = defaultOutput(inp);

        System.out.print("Converting HTML file (" + inp + " -> " + dest + ")... ");

        List<Elem> elems = findDiagrams(html);
        if (elems.isEmpty()) {
            System.out.println();
            System.out.println("HTML document does not contain any <pre> tags with their class attribute set to \"textdiagram\". Nothing to do.");
