            int elemEnd;
            if (closeStart >= 0) {
                int closeEnd = findTagEnd(html, closeStart);
                if (closeEnd < 0) closeEnd = closeStart + 5;
                content = html.substring(contentStart, closeStart);
                elemEnd = closeEnd + 1;
            } else {
                content = html.substring(contentStart);
                elemEnd = contentStart;
            }
            if ("textdiagram".equals(cls)) {
                Elem e = new Elem();
                e.start = start; e.end = elemEnd;
                e.id = attrs.containsKey("id") ? attrs.get("id") : null;
                e.content = extractText(content);
                out.add(e);
            }
            idx = elemEnd > start ? elemEnd : tagEnd + 1;
        }
        return out;
    }

    private static int findPreStart(String lower, int from) {
        int i = lower.indexOf("<pre", from);
        while (i >= 0) {
            if (i + 4 >= lower.length()) return i;
            char c = lower.charAt(i + 4);
            if (c == '>' || c == '/' || Character.isWhitespace(c)) return i;
            i = lower.indexOf("<pre", i + 4);
        }
        return -1;
    }

    private static int findTagEnd(String html, int start) {
        char quote = 0;
        for (int i = start; i < html.length(); i++) {
            char c = html.charAt(i);
            if (quote != 0) {
                if (c == quote) quote = 0;
            } else if (c == '"' || c == '\'') quote = c;
            else if (c == '>') return i;
        }
        return -1;
    }

    private static HashMap<String, String> parseAttrs(String tag) {
        HashMap<String, String> map = new HashMap<String, String>();
        // skip <pre
        int i = 4;
        int n = tag.length();
        while (i < n) {
            while (i < n && (Character.isWhitespace(tag.charAt(i)) || tag.charAt(i) == '/')) i++;
            if (i >= n || tag.charAt(i) == '>') break;
            int nameStart = i;
            while (i < n && !Character.isWhitespace(tag.charAt(i)) && tag.charAt(i) != '=' && tag.charAt(i) != '>' && tag.charAt(i) != '/') i++;
            String name = tag.substring(nameStart, i).toLowerCase();
            while (i < n && Character.isWhitespace(tag.charAt(i))) i++;
            String value = "";
            if (i < n && tag.charAt(i) == '=') {
                i++;
                while (i < n && Character.isWhitespace(tag.charAt(i))) i++;
                if (i < n && (tag.charAt(i) == '"' || tag.charAt(i) == '\'')) {
                    char q = tag.charAt(i); i++;
                    int vs = i;
                    while (i < n && tag.charAt(i) != q) i++;
                    value = tag.substring(vs, i);
                    if (i < n) i++;
                } else {
                    int vs = i;
                    while (i < n && !Character.isWhitespace(tag.charAt(i)) && tag.charAt(i) != '>') i++;
                    value = tag.substring(vs, i);
                }
            }
            if (!name.isEmpty()) map.put(name, decodeEntities(value));
        }
        return map;
    }

    private static String extractText(String content) {
        StringBuilder sb = new StringBuilder();
        // strip HTML comments first roughly
        int i = 0;
        while (i < content.length()) {
            if (content.startsWith("<!--", i)) {
                int e = content.indexOf("-->", i);
                if (e < 0) break;
                i = e + 3;
            } else if (content.charAt(i) == '<') {
                int e = findTagEnd(content, i);
                if (e < 0) {
                    sb.append(content.substring(i));
                    break;
                }
                i = e + 1;
            } else {
                sb.append(content.charAt(i));
                i++;
            }
        }
        return decodeEntities(sb.toString());
    }

    private static String decodeEntities(String s) {
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (c == '&') {
                int semi = s.indexOf(';', i);
                if (semi > i && semi - i <= 12) {
                    String ent = s.substring(i + 1, semi);
                    String rep = entityValue(ent);
                    if (rep != null) {
                        out.append(rep);
                        i = semi + 1;
                        continue;
                    }
                }
            }
            out.append(c);
            i++;
        }
        return out.toString();
    }

    private static String entityValue(String ent) {
        if (ent.equals("lt")) return "<";
        if (ent.equals("gt")) return ">";
        if (ent.equals("amp")) return "&";
        if (ent.equals("quot")) return "\"";
        if (ent.equals("apos")) return "'";
        if (ent.equals("nbsp")) return "\u00a0";
        try {
            if (ent.startsWith("#x") || ent.startsWith("#X")) {
                int v = Integer.parseInt(ent.substring(2), 16);
                return "" + (char) v;
            }
            if (ent.startsWith("#")) {
                int v = Integer.parseInt(ent.substring(1));
                return "" + (char) v;
            }
        } catch (Exception e) { return null; }
        return null;
    }
