                    File outFile = new File(dest);
                    if (outFile.isDirectory()) throw new IOException("Is a directory");
                    FileOutputStream test = new FileOutputStream(outFile);
                    test.close();
                    ok = ImageIO.write(image, "png", outFile);
                }
                if (!ok) throw new IOException("No PNG writer");
            }
        } catch (IOException e) {
            System.err.println("Error: Cannot write to file " + dest);
            System.exit(1);
            return;
        }

        if (!quiet) {
            long secs = (System.currentTimeMillis() - startTime) / 1000;
            System.out.println("Done in " + secs + "sec");
        }
    }

    private static Color parseBackground(String s) {
        if (s == null) return null;
        if (!(s.length() == 6 || s.length() == 8)) return null;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) return null;
        }
        int r = Integer.parseInt(s.substring(0, 2), 16);
        int g = Integer.parseInt(s.substring(2, 4), 16);
        int b = Integer.parseInt(s.substring(4, 6), 16);
        int a = s.length() == 8 ? Integer.parseInt(s.substring(6, 8), 16) : 255;
        return new Color(r, g, b, a);
    }

    private static String replaceExtension(String path, String ext) {
        int slash = path.lastIndexOf('/');
        String dir = slash >= 0 ? path.substring(0, slash + 1) : "";
        String name = slash >= 0 ? path.substring(slash + 1) : path;
        int dot = name.lastIndexOf('.');
        String stem = dot >= 0 ? name.substring(0, dot) : name;
        return dir + stem + "." + ext;
    }

    private static String defaultOutput(String inp, String ext) {
        if (inp.contains("/")) {
            String abs = new File(inp).getAbsolutePath();
            return replaceExtension(abs, ext);
        }
        return replaceExtension(inp, ext);
    }

    private static String alternativeName(String dest) {
        int slash = dest.lastIndexOf('/');
        String dir = slash >= 0 ? dest.substring(0, slash + 1) : "";
        String name = slash >= 0 ? dest.substring(slash + 1) : dest;
        int dot = name.lastIndexOf('.');
        String stem = dot >= 0 ? name.substring(0, dot) : name;
        String ext = dot >= 0 ? name.substring(dot) : "";
        for (int i = 2; ; i++) {
            String candidate = dir + stem + "_" + i + ext;
            if (!new File(candidate).exists()) return candidate;
        }
    }
}
