    private static ParseResult parse(String[] argv) throws CliException {
        ParseResult res = new ParseResult();
        boolean options = true;
        for (int idx = 0; idx < argv.length; idx++) {
            String token = argv[idx];
            if (!options) { res.args.add(token); continue; }
            if (token.equals("--")) { options = false; continue; }
            if (token.startsWith("--") && token.length() > 2) {
                String body = token.substring(2);
                int eq = body.indexOf('=');
                String name = eq >= 0 ? body.substring(0, eq) : body;
                String value = eq >= 0 ? body.substring(eq + 1) : null;
                OptDef exact = null;
                for (OptDef d : ALL) if (d.longOpt != null && d.longOpt.equals(name)) exact = d;
                ArrayList<OptDef> matches = new ArrayList<OptDef>();
                if (exact != null) matches.add(exact);
                else {
                    for (OptDef d : AMBIG_ORDER) if (d.longOpt != null && d.longOpt.startsWith(name)) matches.add(d);
                }
                if (matches.isEmpty()) throw new CliException("Unrecognized option: " + token);
                if (matches.size() > 1) {
                    StringBuilder sb = new StringBuilder();
                    sb.append("Ambiguous option: '--").append(name).append("'  (could be: ");
                    for (int i = 0; i < matches.size(); i++) {
                        if (i > 0) sb.append(", ");
                        sb.append("'").append(matches.get(i).longOpt).append("'");
                    }
                    sb.append(")");
                    throw new CliException(sb.toString());
                }
                OptDef def = matches.get(0);
                if (def.hasArg) {
                    if (value != null) {
                        res.occs.add(new Occ(def, value));
                    } else {
                        String next = idx + 1 < argv.length ? argv[idx + 1] : null;
                        if (next != null && !isOptionToken(next, res)) {
                            res.occs.add(new Occ(def, next)); idx++;
                        } else {
                            throw new CliException("Missing argument for option: " + (def.opt != null ? def.opt : def.longOpt));
                        }
                    }
                } else {
                    res.occs.add(new Occ(def, null));
                    if (value != null) res.args.add(value);
                }
                continue;
            }
            if (token.startsWith("-") && token.length() > 1) {
                // short option cluster
                int i = 1;
                boolean consumed = false;
                while (i < token.length()) {
                    char c = token.charAt(i);
                    OptDef def = byShort(c);
                    if (def == null) throw new CliException("Unrecognized option: " + token);
                    if (def.hasArg) {
                        if (i + 1 < token.length()) {
                            res.occs.add(new Occ(def, token.substring(i + 1)));
                        } else {
                            String next = idx + 1 < argv.length ? argv[idx + 1] : null;
                            if (next != null && !isOptionToken(next, res)) {
                                res.occs.add(new Occ(def, next)); idx++;
                            } else {
                                throw new CliException("Missing argument for option: " + (def.opt != null ? def.opt : def.longOpt));
                            }
                        }
                        consumed = true;
                        break;
                    } else {
                        res.occs.add(new Occ(def, null));
                        i++;
                    }
                }
                continue;
            }
            res.args.add(token);
        }
        return res;
    }

    private static String firstValue(ParseResult r, OptDef def) {
        for (Occ o : r.occs) if (o.def == def) return o.value;
        return null;
    }
    private static boolean has(ParseResult r, OptDef def) {
        for (Occ o : r.occs) if (o.def == def) return true;
        return false;
    }

    public static void main(String[] argv) {
        long startTime = System.currentTimeMillis();
        System.setProperty("java.awt.headless", "true");
        ParseResult parsed;
        try {
            parsed = parse(argv);
        } catch (CliException e) {
            System.out.print(HELP);
            System.err.println(e.getMessage());
            System.exit(2);
            return;
        }
        if (argv.length == 0 || has(parsed, D_HELP)) {
            System.out.print(HELP);
            return;
        }

        ConversionOptions options = new ConversionOptions();
        // fixed-order value validation: scale, background, tabs, encoding
        try {
            String vScale = firstValue(parsed, D_SCALE);
            if (vScale != null) {
                try { options.scale = Float.parseFloat(vScale); }
                catch (NumberFormatException e) { throw new UsageException(e.getMessage()); }
            }
            String vBg = firstValue(parsed, D_B);
            if (vBg != null) {
                Color col = parseBackground(vBg);
                if (col == null) throw new UsageException("Cannot interpret \"" + vBg + "\" as background colour. It needs to be a 6- or 8-digit hex number, depending on whether you have transparency or not (same as HTML).");
                options.background = col; options.hasBackground = true;
            }
            String vTabs = firstValue(parsed, D_TABS);
            if (vTabs != null) {
                try { options.tabs = Integer.parseInt(vTabs); }
                catch (NumberFormatException e) { throw new UsageException(e.getMessage()); }
            }
        } catch (UsageException e) {
            System.out.print(HELP);
            System.err.println("Error: " + e.getMessage());
            System.exit(2);
            return;
        }
        String vEnc = firstValue(parsed, D_ENC);
        if (vEnc != null) {
            try {
                new java.io.InputStreamReader(new java.io.ByteArrayInputStream(new byte[0]), vEnc);
                options.encoding = vEnc;
            } catch (Exception e) {
                System.err.println("Error: " + vEnc);
                System.exit(2);
                return;
            }
        }
        if (parsed.args.isEmpty()) {
            System.out.print(HELP);
            System.err.println("Error: Please provide the input file filename");
            System.exit(2);
            return;
        }
        // boolean / remaining options
        options.noAntialias = has(parsed, D_A);
        options.debug = has(parsed, D_D);
        options.noSeparation = has(parsed, D_E);
        options.html = has(parsed, D_H);
        options.overwrite = has(parsed, D_O);
        options.roundCorners = has(parsed, D_R);
        options.noShadows = has(parsed, D_S);
        options.svg = has(parsed, D_SVG);
        options.transparent = has(parsed, D_T);
        options.verbose = has(parsed, D_V);
        options.fixedSlope = has(parsed, D_W);
        options.svgFontUrl = firstValue(parsed, D_FONT);

        String inp = parsed.args.get(0);
        String outArg = parsed.args.size() > 1 ? parsed.args.get(1) : null;

        boolean quiet = false;
        if (!options.html) {
            if (outArg != null) quiet = outArg.equals("-");
            else quiet = inp.equals("-");
        }

        if (!quiet) {
            System.out.println();
            System.out.println("ditaa version 0.11, Copyright (C) 2004--2017  Efstathios (Stathis) Sideris");
            System.out.println();
            System.out.println("Running with options:");
            for (Occ o : parsed.occs) {
                if (o.def.hasArg) System.out.println(o.def.longOpt + " = " + o.value);
                else System.out.println(o.def.longOpt);
            }
        }

        if (options.html) {
            HTMLConverter.convertHTMLFile(inp, outArg, options);
            return;
        }

        // normal conversion
        File inFile = null;
        if (inp.equals("-")) {
            if (!quiet) System.out.println("Reading standard input");
        } else {
            if (!quiet) System.out.println("Reading file: " + inp);
            inFile = new File(inp);
            if (!inFile.isFile() || !inFile.canRead()) {
                System.err.println("Error: File " + inp + " does not exist");
                System.exit(1);
                return;
            }
        }

        TextGrid grid;
        try {
            InputStream in = inp.equals("-") ? System.in : new FileInputStream(inFile);
            try {
                grid = TextGrid.loadFrom(in, options.encoding, options.tabs);
            } finally {
                if (!inp.equals("-")) in.close();
            }
        } catch (IOException e) {
            System.err.println("Error: File " + inp + " does not exist");
            System.exit(1);
            return;
        }

        if (options.debug) {
            if (!quiet) System.out.println("Using grid:");
            System.out.print(grid.gridString());
        }

        Diagram diagram = new Diagram(grid, options);

        String dest;
        boolean toStdout = false;
        if (outArg != null) {
            dest = outArg;
            toStdout = dest.equals("-");
        } else if (inp.equals("-")) {
            dest = "-";
            toStdout = true;
        } else {
            dest = defaultOutput(inp, options.svg ? "svg" : "png");
            if (!options.overwrite) {
                if (new File(dest).exists()) dest = alternativeName(dest);
            }
        }
        if (!quiet) System.out.println("Rendering to file: " + dest);

        try {
            if (options.svg) {
                String svg = diagram.toSVG();
                if (toStdout) {
                    System.out.write(svg.getBytes("UTF-8"));
                    System.out.flush();
                } else {
                    FileOutputStream fos = new FileOutputStream(new File(dest));
                    try { fos.write(svg.getBytes("UTF-8")); } finally { fos.close(); }
                }
            } else {
                BufferedImage image = diagram.renderToImage();
                boolean ok;
                if (toStdout) {
                    ok = ImageIO.write(image, "png", System.out);
                    System.out.flush();
                } else {
                    // match cannot-write detection for directories / read-only targets
                    File outFile = new File(dest);
                    if (outFile.isDirectory()) throw new IOException("Is a directory");
                    FileOutputStream test = new FileOutputStream(outFile);
                    test.close();
                    ok = ImageIO.write(image, "png", outFile);
                }
                if (!ok) throw new IOException("No PNG writer");
            }
        } catch (IOException e) {
            System.err.println("Error: Cannot write to file " + dest);
            System.exit(1);
            return;
        }

        if (!quiet) {
            long secs = (System.currentTimeMillis() - startTime) / 1000;
            System.out.println("Done in " + secs + "sec");
        }
    }

    private static Color parseBackground(String s) {
        if (s == null) return null;
        if (!(s.length() == 6 || s.length() == 8)) return null;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) return null;
        }
        int r = Integer.parseInt(s.substring(0, 2), 16);
        int g = Integer.parseInt(s.substring(2, 4), 16);
        int b = Integer.parseInt(s.substring(4, 6), 16);
        int a = s.length() == 8 ? Integer.parseInt(s.substring(6, 8), 16) : 255;
        return new Color(r, g, b, a);
    }

    private static String replaceExtension(String path, String ext) {
        int slash = path.lastIndexOf('/');
        String dir = slash >= 0 ? path.substring(0, slash + 1) : "";
        String name = slash >= 0 ? path.substring(slash + 1) : path;
        int dot = name.lastIndexOf('.');
        String stem = dot >= 0 ? name.substring(0, dot) : name;
        return dir + stem + "." + ext;
    }

    private static String defaultOutput(String inp, String ext) {
        if (inp.contains("/")) {
            String abs = new File(inp).getAbsolutePath();
            return replaceExtension(abs, ext);
        }
        return replaceExtension(inp, ext);
    }

    private static String alternativeName(String dest) {
        int slash = dest.lastIndexOf('/');
        String dir = slash >= 0 ? dest.substring(0, slash + 1) : "";
        String name = slash >= 0 ? dest.substring(slash + 1) : dest;
        int dot = name.lastIndexOf('.');
        String stem = dot >= 0 ? name.substring(0, dot) : name;
        String ext = dot >= 0 ? name.substring(dot) : "";
        for (int i = 2; ; i++) {
            String candidate = dir + stem + "_" + i + ext;
            if (!new File(candidate).exists()) return candidate;
        }
    }
}
